<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free PDF Rotator Online','description'=>'Rotate all PDF pages clockwise by 90, 180 or 270 degrees and download the result.','url'=>'https://smarttoolz.in/tools/pdf-rotate/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">PDF ROTATOR</span><h1>Rotate PDF</h1><p>Rotate every page in a PDF and download the corrected document.</p></section><section class="tool-workspace"><div class="tool-panel"><label>PDF file<input id="f" type="file" accept="application/pdf"></label><label>Rotation<select id="r"><option value="90">90° clockwise</option><option value="180">180°</option><option value="270">270° clockwise</option></select></label><button id="go" class="tool-btn">Rotate & Download</button><p id="out"></p></div></section></main><script src="https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js"></script><script>(()=>{const $=id=>document.getElementById(id);$('go').onclick=async()=>{let f=$('f').files[0];if(!f){$('out').textContent='Choose a PDF.';return}try{let p=await PDFLib.PDFDocument.load(await f.arrayBuffer()),r=+$('r').value;p.getPages().forEach(x=>x.setRotation(PDFLib.degrees(x.getRotation().angle+r)));let b=new Blob([await p.save()],{type:'application/pdf'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='rotated.pdf';a.click();$('out').textContent='PDF rotated successfully.'}catch(e){$('out').textContent='Could not rotate this PDF.'}}})();</script><?php smarttoolz_tool_page_end(); ?>